<?php

namespace Ecompetence\EcompetenceBundle\Repository;
Use Doctrine\ORM\Query\Expr\Join;
/**
 * AgentcompetenceRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class AgentcompetenceRepository extends \Doctrine\ORM\EntityRepository
{
     public function listecompetence($id)
    {
            $qb = $this->createQueryBuilder('ag')
            ->select('d.id')
            ->innerJoin('EcompetenceBundle:Domaine', 'd', Join::WITH,'d.id = ag.competence')
            ->innerJoin('AgentBundle:Agent', 'a', Join::WITH,'a.id = ag.agent') 
            ->Where('a.id = :id')
            ->setParameter('id',$id) 
           
           ;
       return $qb->getQuery()->getResult();
}
}
